package com.worshiparchive.band;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.Color;
import android.net.ConnectivityManager;
import android.net.Network;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Full Android Leader workspace: local library host plus the shared desktop interface. */
public final class LeaderActivity extends Activity {
    private static final int PICK_CLOUD_FOLDER=4711;
    private static final int PICK_TEXT_FILES=4712;
    private static final int SAVE_TEXT_FILE=4713;
    private WebView web; private FrameLayout root; private LocalLeaderServer server; private LeaderAdvertisement advertisement; private SharedPreferences prefs; private volatile String viewport="{}"; private boolean stopping;
    private ConnectivityManager connectivity; private ConnectivityManager.NetworkCallback networkCallback; private ValueCallback<Uri[]> pendingFiles; private String pendingSaveName; private String pendingSaveContents;
    @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("leader",MODE_PRIVATE);if(!prefs.contains("deviceId"))prefs.edit().putString("deviceId",UUID.randomUUID().toString()).apply();
        root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(28,29,31));setContentView(root);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        root.setOnApplyWindowInsetsListener((view,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        try{String id=prefs.getString("deviceId",UUID.randomUUID().toString());server=new LocalLeaderServer(7374,this,prefs,getFilesDir(),id,path->getAssets().open("ui/"+path));observeConnectivity();advertisement=new LeaderAdvertisement(this,server.port(),id,prefs.getString("name","Worship Archive Android"));startForegroundService(new Intent(this,LeaderKeepAliveService.class));
            web=new WebView(this);web.setBackgroundColor(Color.rgb(28,29,31));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setDatabaseEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setSupportZoom(false);settings.setBuiltInZoomControls(false);settings.setDisplayZoomControls(false);settings.setTextZoom(100);settings.setMinimumFontSize(1);settings.setMinimumLogicalFontSize(1);settings.setUseWideViewPort(true);settings.setLoadWithOverviewMode(false);
            web.addJavascriptInterface(new AndroidBridge(),"worshipAndroid");web.addOnLayoutChangeListener((view,l,t,r,b,ol,ot,or,ob)->publishViewport(false));
            web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return reject(request.getUrl());}@Override public boolean shouldOverrideUrlLoading(WebView view,String url){return reject(Uri.parse(url));}@Override public void onPageFinished(WebView view,String url){publishViewport(true);}});
            web.setWebChromeClient(new WebChromeClient(){@Override public boolean onConsoleMessage(ConsoleMessage message){android.util.Log.d("WorshipLeader",message.message());return super.onConsoleMessage(message);}@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(pendingFiles!=null)pendingFiles.onReceiveValue(null);pendingFiles=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,PICK_TEXT_FILES);return true;}catch(Exception error){pendingFiles=null;callback.onReceiveValue(null);Toast.makeText(LeaderActivity.this,"No file picker is available.",Toast.LENGTH_LONG).show();return false;}}});
            root.addView(web,new FrameLayout.LayoutParams(-1,-1));web.loadUrl(server.origin()+"/");
        }catch(Exception error){stopService(new Intent(this,LeaderKeepAliveService.class));if(advertisement!=null)advertisement.close();if(server!=null)server.close();new AlertDialog.Builder(this).setTitle("Worship Archive Leader").setMessage("The Leader could not start. "+error.getMessage()).setPositiveButton(android.R.string.ok,(dialog,which)->finish()).show();}
    }
    private boolean reject(Uri uri){if(server!=null&&"http".equals(uri.getScheme())&&"127.0.0.1".equals(uri.getHost())&&uri.getPort()==server.port())return false;try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){}return true;}
    private void publishViewport(boolean force){if(web==null||stopping||web.getWidth()<=0||web.getHeight()<=0)return;float density=getResources().getDisplayMetrics().density;String next="{\"width\":"+(web.getWidth()/density)+",\"height\":"+(web.getHeight()/density)+",\"shortSide\":"+getResources().getConfiguration().smallestScreenWidthDp+"}";if(!force&&next.equals(viewport))return;viewport=next;web.post(()->{if(!stopping&&web!=null)web.evaluateJavascript("window.dispatchEvent(new Event('worship-android-viewport'))",null);});}
    @Override public void onConfigurationChanged(Configuration configuration){super.onConfigurationChanged(configuration);if(web!=null){web.requestLayout();web.invalidate();web.post(()->publishViewport(true));}}
    @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else super.onBackPressed();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);
        if(request==PICK_TEXT_FILES){ValueCallback<Uri[]> callback=pendingFiles;pendingFiles=null;if(callback==null)return;if(result!=RESULT_OK||data==null){callback.onReceiveValue(null);return;}List<Uri> values=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)values.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)values.add(data.getData());callback.onReceiveValue(values.toArray(new Uri[0]));return;}
        if(request==SAVE_TEXT_FILE){String contents=pendingSaveContents;pendingSaveContents=null;pendingSaveName=null;if(result!=RESULT_OK||data==null||data.getData()==null||contents==null)return;try(OutputStream output=getContentResolver().openOutputStream(data.getData(),"wt")){if(output==null)throw new java.io.IOException("The selected file could not be opened");output.write(contents.getBytes(StandardCharsets.UTF_8));Toast.makeText(this,"Backup saved.",Toast.LENGTH_SHORT).show();}catch(Exception error){Toast.makeText(this,"Could not save the backup: "+error.getMessage(),Toast.LENGTH_LONG).show();}return;}
        if(request!=PICK_CLOUD_FOLDER||result!=RESULT_OK||data==null||data.getData()==null)return;try{server.selectCloudFolder(data.getData(),data.getFlags());cloudChanged();}catch(Exception error){Toast.makeText(this,"Could not connect the selected cloud folder: "+error.getMessage(),Toast.LENGTH_LONG).show();}}
    private void cloudChanged(){if(web!=null)web.post(()->web.evaluateJavascript("window.dispatchEvent(new Event('worship-cloud-changed'))",null));}
    private void chooseCloudFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(intent,PICK_CLOUD_FOLDER);}
    private void openCloudFolder(){Uri uri=server==null?null:server.cloudFolder();if(uri==null)return;try{Intent intent=new Intent(Intent.ACTION_VIEW,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception error){Toast.makeText(this,"Open the selected folder from your cloud drive app.",Toast.LENGTH_LONG).show();}}
    private void saveTextFile(String name,String contents){pendingSaveName=name;pendingSaveContents=contents;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,name);try{startActivityForResult(intent,SAVE_TEXT_FILE);}catch(Exception error){pendingSaveName=null;pendingSaveContents=null;Toast.makeText(this,"No document saver is available.",Toast.LENGTH_LONG).show();}}
    private void observeConnectivity(){connectivity=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);if(connectivity==null)return;networkCallback=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network network){LocalLeaderServer current=server;if(current!=null)current.networkAvailable();}};connectivity.registerDefaultNetworkCallback(networkCallback);}
    @Override public void onResume(){super.onResume();if(web!=null){web.onResume();web.post(()->publishViewport(true));}}
    @Override public void onPause(){if(web!=null)web.onPause();super.onPause();}
    @Override public void onDestroy(){stopping=true;if(connectivity!=null&&networkCallback!=null)try{connectivity.unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}if(pendingFiles!=null){pendingFiles.onReceiveValue(null);pendingFiles=null;}stopService(new Intent(this,LeaderKeepAliveService.class));if(advertisement!=null)advertisement.close();if(server!=null)server.close();if(web!=null){root.removeView(web);web.destroy();}super.onDestroy();}
    public final class AndroidBridge{@JavascriptInterface public String getViewport(){return viewport;}@JavascriptInterface public boolean isLeader(){return true;}@JavascriptInterface public void openConnectionSettings(){runOnUiThread(()->Toast.makeText(LeaderActivity.this,"Connection addresses are available in Settings",Toast.LENGTH_SHORT).show());}@JavascriptInterface public void chooseCloudSyncDir(){runOnUiThread(LeaderActivity.this::chooseCloudFolder);}@JavascriptInterface public void revealCloudSyncDir(){runOnUiThread(LeaderActivity.this::openCloudFolder);}@JavascriptInterface public void disconnectCloudSync(){runOnUiThread(()->{if(server!=null)server.disconnectCloudFolder();cloudChanged();});}@JavascriptInterface public void saveTextFile(String name,String contents){runOnUiThread(()->LeaderActivity.this.saveTextFile(name,contents));}}
}
